import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { docsSchema } from '@astrojs/starlight/schema';

// An explicit list keeps internal planning and qualification records out of
// the public site. `reference/**` is generated by tools/generate-astro-api.sh.
export const collections = {
  docs: defineCollection({
    loader: glob({
      base: new URL('../../docs', import.meta.url).pathname,
      pattern: [
        'index.mdx',
        'quickstart-toolchain.md',
        'run-on-aros.md',
        'targets-and-abis.md',
        'compatibility.md',
        'consumer-guide.md',
        'api.md',
        'api/aros.md',
        'api/aros-mui.md',
        'api/aros-timer.md',
        'api/aros-graphics.md',
        'api/aros-intuition.md',
        'build-system.md',
        'architecture.md',
        'mui-hello.mdx',
        'sha256sum.md',
        'troubleshooting.md',
        'editor-setup.md',
        'glossary.md',
        'releases.md',
        'changelog.md',
        'platform-roadmap.md',
        'reference/**/*.md',
      ],
    }),
    schema: docsSchema(),
  }),
};
